'use strict'

import resource from '../resource'
import { overlaps } from '../utils/box'
import { directionOf } from './enemies/common'
import { revealAt } from './secret'
import { TILE_WIDTH, TILE_HEIGHT, SECRET_FLAME } from '../constant'

// Measured in the ROM (object $10, states $21 then $22): the flame appears one tile in front of Link,
// goes one more tile at half an NES pixel a frame (one display pixel a game step), then burns 62 frames.
// A bush hiding an entrance turns into the stairs when it goes out
const MOVE_STEPS = TILE_WIDTH
const BURN_STEPS = 62
export const FLAME_STEPS = MOVE_STEPS + BURN_STEPS
// Measured: as strong as the wooden sword, and it burns an enemy again each time it is no longer hurt (a
// blue Moblin, 3 points of life, dies in one flame). Link walking into it loses half a heart
export const FLAME_DAMAGE = 1
export const FLAME_LINK_DAMAGE = 0.5
// The flame of the cave, which flips every few frames
const FLAME_SPRITE = 'misc_flamme'
const FRAME_STEPS = 8

export class Flame {
  constructor (x, y, [dx, dy]) {
    this.x = x
    this.y = y
    this.dx = dx
    this.dy = dy
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.steps = 0
    this.done = false
  }

  getBox () {
    return { x: this.x, y: this.y, width: this.width, height: this.height }
  }

  process (map, link) {
    this.steps++
    if (this.steps <= MOVE_STEPS) {
      this.x += this.dx
      this.y += this.dy
    }
    const box = this.getBox()
    for (const enemy of map.activeEnemies) {
      if (!enemy.isVulnerable || !overlaps(box, enemy.getBox())) {
        continue
      }
      enemy.hit(link, { damage: FLAME_DAMAGE, direction: directionOf(enemy.x - this.x, enemy.y - this.y) })
    }
    if (overlaps(box, link.getBodyBox())) {
      link.hurt(FLAME_LINK_DAMAGE, box)
    }
    if (this.steps >= FLAME_STEPS) {
      revealAt(map, box, SECRET_FLAME)
      this.done = true
    }
  }

  draw (context) {
    const sprite = resource.getSprite(FLAME_SPRITE)
    const images = sprite?.images
    const image = images?.length ? images[Math.floor(this.steps / FRAME_STEPS) % images.length] : sprite
    image?.draw(context, this.x, this.y, this.width, this.height)
  }
}
